fire:
if msg.kind == 'X':
    handle_cancel(msg)
elif msg.kind == 'Z':
    handle_close(msg)

if op == 'Q':
    quit()
elif op == 'W':
    write()

quiet:
if msg.kind == cancel:
    handle_cancel(msg)
elif msg.kind == close:
    handle_close(msg)

if op == quit_op:
    quit()
elif op == write_op:
    write()
